SWITCHES = {
    "use_cotr": True, "use_prediction_kd": True, "use_gopd": True,
    "use_fsrd": True, "use_rceb": False,
}
TEST_CSV = (
    "O,C,E,A,N,racc,r2\n"
    "0.9154250249266624,0.9224440306425095,0.9179041236639023,"
    "0.9135913327336311,0.9150239378213882,0.9168776899576188,"
    "0.4903276562690735\n"
)


def test_experiment_a_reported_aggregates_keep_validation_test_and_provenance_separate(tmp_path):
    analyze = api()
    root = tmp_path / "sanitized-a"
    root.mkdir()
    # JSON is a YAML subset; no producer-specific YAML machinery is needed.
    (root / "hparams.yaml").write_text(json.dumps({"config": {
        "n_epochs": 100, **SWITCHES}}), encoding="utf-8")
    (root / "history.json").write_text(json.dumps({"valid": {"app": CURVES}}), encoding="utf-8")
    (root / "metrics_test.csv").write_text(TEST_CSV, encoding="utf-8")
    before = {p.name: p.read_bytes() for p in root.iterdir()}
    result = analyze(str(root), config_paths=[(k,) for k in SWITCHES],
                     test_metrics_file="metrics_test.csv",
                     test_metric_specs=[spec("test_r2", "r2"), spec("test_racc", "racc")],
                     include_diagnostics=True)
    for name, expected in (("r2", 0.4677645266056061), ("racc", 0.9168932095170022)):
        metric = result["validation_metrics"][name]
        assert math.isclose(metric["best_value"], expected, rel_tol=0, abs_tol=1e-6)
        assert (metric["best_epoch"], metric["last_epoch"], metric["record_count"]) == (71, 91, 92)
    assert result["configuration"]["n_epochs"] == 100
    assert not any(k in result["configuration"] for k in SWITCHES)
    fields = result["configuration_evidence"]["fields"]
    assert [(f["path"], f["value"]) for f in fields] == [([k], v) for k, v in SWITCHES.items()]
    assert all(f["evidence_kind"] == "configuration_declared" for f in fields)
    test = result["test_results"]
    assert test["status"] == "available"
    assert math.isclose(test["metrics"]["test_r2"]["value"], 0.4903276562690735,
                        rel_tol=0, abs_tol=1e-6)
    assert math.isclose(test["metrics"]["test_racc"]["value"], 0.9168776899576188,
                        rel_tol=0, abs_tol=1e-6)
    assert test["metrics"]["test_r2"]["value"] != result["validation_metrics"]["r2"]["best_value"]
    assert_provenance(test)
    assert {p.name: p.read_bytes() for p in root.iterdir()} == before
